from decimal import Decimal, ROUND_HALF_UP


def total_cents(amounts):
    """Sum a list of decimal amount strings like '12.30' and return integer cents."""
    total = sum(
        (Decimal(a) * 100).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
        for a in amounts
    )
    return int(total)

